import heapq

def match(orders):
    trades = []
    buy_heap = []   # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    book = {}       # id -> dict with side, price, qty, seq, active
    seq_counter = 0

    def clean_buy():
        while buy_heap:
            negprice, seq, oid = buy_heap[0]
            rec = book.get(oid)
            if rec is None or not rec['active'] or rec['qty'] <= 0:
                heapq.heappop(buy_heap)
            else:
                break

    def clean_sell():
        while sell_heap:
            price, seq, oid = sell_heap[0]
            rec = book.get(oid)
            if rec is None or not rec['active'] or rec['qty'] <= 0:
                heapq.heappop(sell_heap)
            else:
                break

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            rec = book.get(oid)
            if rec is not None and rec['active'] and rec['qty'] > 0:
                rec['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            while remaining > 0:
                clean_sell()
                if not sell_heap:
                    break
                top_price, top_seq, top_id = sell_heap[0]
                if typ != 'market' and price < top_price:
                    break
                rec = book[top_id]
                trade_qty = min(remaining, rec['qty'])
                trades.append([oid, top_id, top_price, trade_qty])
                remaining -= trade_qty
                rec['qty'] -= trade_qty
                if rec['qty'] == 0:
                    rec['active'] = False
                    heapq.heappop(sell_heap)
            if typ == 'limit' and remaining > 0:
                seq_counter += 1
                book[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'seq': seq_counter, 'active': True}
                heapq.heappush(buy_heap, (-price, seq_counter, oid))
        else:  # sell
            while remaining > 0:
                clean_buy()
                if not buy_heap:
                    break
                negprice, top_seq, top_id = buy_heap[0]
                top_price = -negprice
                if typ != 'market' and price > top_price:
                    break
                rec = book[top_id]
                trade_qty = min(remaining, rec['qty'])
                trades.append([top_id, oid, top_price, trade_qty])
                remaining -= trade_qty
                rec['qty'] -= trade_qty
                if rec['qty'] == 0:
                    rec['active'] = False
                    heapq.heappop(buy_heap)
            if typ == 'limit' and remaining > 0:
                seq_counter += 1
                book[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'seq': seq_counter, 'active': True}
                heapq.heappush(sell_heap, (price, seq_counter, oid))

    return trades

